/**
 * Browser copy of the Python risk engine (engine/pe_risk), for the standalone website.
 *
 * It must give the same numbers as the Python engine: web/tests/parity.test.ts checks it against
 * cases generated by engine/tools/make_parity_cases.py. Change both together.
 */
import rawCoef from "../../../engine/pe_risk/coefficients/fmf_11_13_v1.json?raw";

/* eslint-disable @typescript-eslint/no-explicit-any */
type Json = any;

export const COEF: { label: string; checksum: string; data: Json } = (() => {
  const data = JSON.parse(rawCoef);
  return { label: data.label ?? "fmf_11_13_v1", checksum: __COEF_SHA256__, data };
})();

export type Ethnicity = "white" | "afro_caribbean" | "south_asian" | "east_asian" | "mixed";
export type Conception = "spontaneous" | "ovulation_drugs" | "ivf";
export type Diabetes = "none" | "type1" | "type2_insulin" | "type2_no_insulin";
export type Analyser = "delfia_xpress" | "cobas_e411" | "kryptor";

export type PreviousPregnancy = { had_pe: boolean; ga_at_delivery_weeks: number; interval_years: number };
export type MaternalFactors = {
  age_years: number;
  weight_kg: number;
  height_cm: number;
  ethnicity: Ethnicity;
  smoker: boolean;
  conception: Conception;
  chronic_hypertension: boolean;
  diabetes: Diabetes;
  sle_or_aps: boolean;
  family_history_pe: boolean;
  previous: PreviousPregnancy | null;
};
export type Biomarkers = {
  map_mmhg?: number | null;
  map_mom?: number | null;
  utpi_left?: number | null;
  utpi_right?: number | null;
  utpi_mom?: number | null;
  plgf_pg_ml?: number | null;
  plgf_analyser?: Analyser | null;
  plgf_mom?: number | null;
  plgf_ga_days?: number | null;
};
export type RiskEstimate = { cutoff_weeks: number; probability: number; one_in: number };
export type RiskReport = {
  model_label: string;
  model_checksum: string;
  prior_mean_weeks: number;
  prior_sd_weeks: number;
  moms: Record<string, number>;
  maternal_factors_only: RiskEstimate[];
  combined: RiskEstimate[] | null;
  markers_used: string[];
  warnings: string[];
};

/** Python's round(): halves go to the even neighbour. */
export function roundHalfEven(x: number): number {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

/** Python's round(x, n): correct rounding of the exact binary value, ties to even.
 * toFixed already rounds the exact value; only an exact tie needs the even rule. */
export function roundTo(x: number, n: number): number {
  const exact = Math.abs(x).toFixed(Math.min(100, n + 80)); // exact decimal expansion of the double
  const rest = exact.slice(exact.indexOf(".") + 1 + n);
  if (/^50*$/.test(rest)) {
    const down = Number(exact.slice(0, exact.indexOf(".") + 1 + n).replace(/\.$/, ""));
    const lastDigit = Number(exact.replace(".", "").slice(0, exact.indexOf(".") + n).slice(-1));
    const v = lastDigit % 2 === 0 ? down : down + 10 ** -n;
    return Math.sign(x) * Number(v.toFixed(n));
  }
  return Number(x.toFixed(n));
}

/** Python's str() of a float, used inside messages so the VI translations match. */
export function pyFloat(x: number): string {
  return Number.isInteger(x) ? `${x}.0` : String(x);
}

/** Python's format(x, "g"). */
export function pyG(x: number): string {
  if (x === 0) return "0";
  const exp = Math.floor(Math.log10(Math.abs(x)));
  if (exp < -4 || exp >= 6) {
    const [m, e] = x.toExponential(5).split("e");
    const mm = m.replace(/\.?0+$/, "");
    const ee = Number(e);
    return `${mm}e${ee < 0 ? "-" : "+"}${String(Math.abs(ee)).padStart(2, "0")}`;
  }
  return String(Number(x.toPrecision(6)));
}

export function oneIn(p: number): number {
  return p <= 0 ? 10 ** 7 : Math.max(1, roundHalfEven(1 / p));
}

/* ----------------------------------------------------------------------------- dating */

export function gaDaysFromCrl(crl: number): number {
  if (!(crl >= 45 && crl <= 84)) throw new Error(`CRL ${pyFloat(crl)} mm is outside 45-84 mm (11+0 to 13+6 weeks)`);
  return 8.052 * Math.sqrt(crl) + 23.73;
}
export function gaDaysFromBpd(bpd: number): number {
  if (!(bpd >= 15 && bpd <= 28)) throw new Error(`BPD ${pyFloat(bpd)} mm is outside 15-28 mm (about 11-13 weeks)`);
  return (bpd + 16.33798) / 0.4299;
}
export const bpdMedianMm = (ga: number) => 0.4299 * ga - 16.33798;

const DAY = 86_400_000;
export const parseDate = (s: string) => {
  const [y, m, d] = s.split("-").map(Number);
  return Date.UTC(y, m - 1, d);
};
export const daysBetween = (a: string, b: string) => Math.round((parseDate(b) - parseDate(a)) / DAY);
export const addDays = (s: string, n: number) => new Date(parseDate(s) + n * DAY).toISOString().slice(0, 10);

export function gaDaysFromIvf(transfer: string, embryoAge: number, exam: string): number {
  if (![3, 5, 6].includes(embryoAge)) throw new Error("embryo age at transfer must be 3, 5 or 6 days");
  return daysBetween(transfer, exam) + embryoAge + 14;
}
export function gaDaysManual(weeks: number, days: number): number {
  if (!(days >= 0 && days <= 6)) throw new Error("days must be 0-6");
  return weeks * 7 + days;
}
export const eddFromGa = (ga: number, exam: string) => addDays(exam, roundHalfEven(280 - ga));
export const formatGa = (ga: number) => {
  const d = Math.trunc(ga);
  return `${Math.floor(d / 7)}+${d % 7}`;
};

/* ----------------------------------------------------------------------------- MoM */

function diabetesTerm(m: Json, d: Diabetes): number {
  const key = { type1: "diabetes_type1", type2_insulin: "diabetes_type2_insulin", type2_no_insulin: "diabetes_type2_no_insulin" }[
    d as Exclude<Diabetes, "none">
  ];
  return key ? (m[key] ?? 0) : 0;
}

function parityTerms(m: Json, mf: MaternalFactors): number {
  const prev = mf.previous;
  if (!prev) return 0;
  if (prev.had_pe) return m.parous_previous_pe ?? 0;
  return (m.parous_no_previous_pe ?? 0) + (m.parous_no_previous_pe_x_interval_minus_2 ?? 0) * (prev.interval_years - 2);
}

const eth = (m: Json, e: Ethnicity) => m.ethnicity[e] ?? 0;

export function expectedLog10Map(gaDays: number, mf: MaternalFactors): number {
  const m = COEF.data.mom.map;
  const ga = gaDays - 77;
  const wt = mf.weight_kg - 69;
  let y =
    m.intercept + m.ga * ga + m.ga_squared * ga ** 2 + m.weight * wt + m.weight_squared * wt ** 2 +
    m.height * (mf.height_cm - 164) + eth(m, mf.ethnicity) + diabetesTerm(m, mf.diabetes) + parityTerms(m, mf);
  if (mf.smoker) y += m.smoker;
  if (mf.chronic_hypertension) y += m.chronic_hypertension + m.chronic_hypertension_x_weight * wt;
  if (mf.family_history_pe) y += m.family_history_pe;
  return y;
}

export function expectedLog10Utpi(gaDays: number, mf: MaternalFactors): number {
  const m = COEF.data.mom.utpi;
  const ga = gaDays - 77;
  const wt = mf.weight_kg - 69;
  return (
    m.intercept + m.ga * ga + m.weight * wt + m.weight_squared * wt ** 2 + m.age * (mf.age_years - 35) +
    eth(m, mf.ethnicity) + diabetesTerm(m, mf.diabetes) + parityTerms(m, mf)
  );
}

export function expectedLog10Plgf(gaDays: number, mf: MaternalFactors, analyser: Analyser): number {
  const m = COEF.data.mom.plgf;
  const ga = gaDays - 77;
  const wt = mf.weight_kg - 69;
  let y =
    m.intercept_by_analyser[analyser] + m.ga * ga + m.ga_squared * ga ** 2 + m.weight * wt + m.weight_squared * wt ** 2 +
    m.age * (mf.age_years - 35) + eth(m, mf.ethnicity) + diabetesTerm(m, mf.diabetes) + parityTerms(m, mf);
  if (mf.smoker) y += m.smoker;
  if (mf.conception === "ivf") y += m.ivf;
  return y;
}

export function meanArterialPressure(readings: [number, number][]): number {
  if (!readings.length) throw new Error("at least one blood pressure reading is required");
  return readings.map(([s, d]) => d + (s - d) / 3).reduce((a, b) => a + b, 0) / readings.length;
}

/* ----------------------------------------------------------------------------- prior */

export function priorTerms(mf: MaternalFactors, warnings?: string[]): [string, number][] {
  const c = COEF.data.prior;
  const terms: [string, number][] = [["intercept", c.intercept]];
  const add = (name: string, v: number) => {
    if (v !== 0) terms.push([name, v]);
  };
  if (mf.age_years > 35) add("age_over_35", c.age_over_35_per_year * (mf.age_years - 35));
  add("height", c.height_minus_164_per_cm * (mf.height_cm - 164));
  add("ethnicity", c.ethnicity[mf.ethnicity] ?? 0);
  if (mf.chronic_hypertension) add("chronic_hypertension", c.chronic_hypertension);
  if (mf.sle_or_aps) add("sle_or_aps", c.sle_or_aps);
  if (mf.conception === "ivf") add("ivf", c.ivf);

  const prev = mf.previous;
  if (prev) {
    const sq = (prev.ga_at_delivery_weeks - 24) ** 2;
    if (prev.had_pe) {
      const p = c.parous_previous_pe;
      add("parous_previous_pe", p.intercept + p.prev_ga_minus_24_squared * sq);
    } else {
      const p = c.parous_no_previous_pe;
      const floor = c.implementation_choices.min_interval_years;
      let interval = prev.interval_years;
      if (interval < floor) {
        warnings?.push(`Interpregnancy interval ${pyG(interval)} y raised to ${pyG(floor)} y for the prior model (unvalidated bound).`);
        interval = floor;
      }
      add(
        "parous_no_previous_pe",
        p.intercept + p.interval_years_pow_minus_1 * interval ** -1 + p.interval_years_pow_minus_0_5 * interval ** -0.5 +
          p.prev_ga_minus_24_squared * sq,
      );
    }
  }
  if (!mf.chronic_hypertension) {
    const w = c.without_chronic_hypertension;
    add("weight", w.weight_minus_69_per_kg * (mf.weight_kg - 69));
    if (mf.family_history_pe) add("family_history_pe", w.family_history_pe);
    if (mf.diabetes !== "none") add("diabetes", w.diabetes_type1_or_2);
  }
  return terms;
}

/* ----------------------------------------------------------------------------- likelihood */

function markerMean(t: number, p: Json): number {
  if ("b0" in p) {
    const t0 = -p.b0 / p.b1_per_week;
    return t < t0 ? p.b0 + p.b1_per_week * t : 0;
  }
  const t0 = p.ga_meets_unaffected_weeks;
  return t < t0 ? p.slope_per_week * (t - t0) : 0;
}

function covariance(markers: string[]): number[][] {
  const cov = COEF.data.likelihood.covariance;
  const idx = markers.map((m) => cov.order.indexOf(m));
  if (cov.matrix) return idx.map((i) => idx.map((j) => cov.matrix[i][j]));
  return idx.map((i) => idx.map((j) => cov.correlation[i][j] * cov.sd[i] * cov.sd[j]));
}

function invert(a: number[][]): number[][] {
  const n = a.length;
  const m = a.map((row, i) => [...row, ...Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))]);
  for (let c = 0; c < n; c++) {
    let p = c;
    for (let r = c + 1; r < n; r++) if (Math.abs(m[r][c]) > Math.abs(m[p][c])) p = r;
    [m[c], m[p]] = [m[p], m[c]];
    const d = m[c][c];
    for (let k = 0; k < 2 * n; k++) m[c][k] /= d;
    for (let r = 0; r < n; r++) {
      if (r === c) continue;
      const f = m[r][c];
      for (let k = 0; k < 2 * n; k++) m[r][k] -= f * m[c][k];
    }
  }
  return m.map((row) => row.slice(n));
}

/* ----------------------------------------------------------------------------- risk */

const DEFAULT_CUTOFFS = [32, 37];
const WINDOW_DAYS = [77, 97];

/** erf by its Taylor series with positive terms (no cancellation), or the continued fraction for erfc. */
function erf(x: number): number {
  const ax = Math.abs(x);
  if (ax > 6) return Math.sign(x);
  let v: number;
  if (ax < 3) {
    let term = ax;
    let sum = ax;
    for (let n = 1; n < 200; n++) {
      term *= (2 * ax * ax) / (2 * n + 1);
      sum += term;
      if (term < sum * 1e-17) break;
    }
    v = (2 / Math.sqrt(Math.PI)) * Math.exp(-ax * ax) * sum;
  } else {
    // Lentz continued fraction for erfc.
    const tiny = 1e-300;
    let f = ax;
    let C = ax;
    let D = 0;
    for (let n = 1; n < 300; n++) {
      const an = n / 2;
      D = ax + an * D;
      D = D === 0 ? tiny : 1 / D;
      C = ax + an / C;
      if (C === 0) C = tiny;
      const delta = C * D;
      f *= delta;
      if (Math.abs(delta - 1) < 1e-16) break;
    }
    v = 1 - Math.exp(-ax * ax) / Math.sqrt(Math.PI) / f;
  }
  return x < 0 ? -v : v;
}
const normCdf = (z: number) => 0.5 * (1 + erf(z / Math.SQRT2));

export function priorRisk(mu: number, sd: number, gaWeeks: number, cutoff: number): number {
  if (cutoff <= gaWeeks) return 0;
  const fg = normCdf((gaWeeks - mu) / sd);
  const fc = normCdf((cutoff - mu) / sd);
  return (fc - fg) / (1 - fg);
}

export function posteriorRisks(mu: number, sd: number, gaWeeks: number, log10Moms: Record<string, number>, cutoffs: number[]): number[] {
  const markers = Object.keys(log10Moms);
  const params = COEF.data.likelihood.markers;
  const x = markers.map((m) => log10Moms[m]);
  const prec = invert(covariance(markers));
  const t: number[] = [];
  for (let i = 0; i < 12000; i++) {
    const v = i * 0.01; // numpy.arange(0, 120, 0.01)
    if (v > gaWeeks) t.push(v);
  }
  const lp = t.map((ti) => {
    const r = markers.map((m, k) => x[k] - markerMean(ti, params[m]));
    let q = 0;
    for (let i = 0; i < r.length; i++) for (let j = 0; j < r.length; j++) q += r[i] * prec[i][j] * r[j];
    return -0.5 * ((ti - mu) / sd) ** 2 - 0.5 * q;
  });
  const max = Math.max(...lp);
  const w = lp.map((v) => Math.exp(v - max));
  const trapz = (n: number) => {
    let s = 0;
    for (let i = 1; i < n; i++) s += ((w[i] + w[i - 1]) / 2) * (t[i] - t[i - 1]);
    return s;
  };
  const total = trapz(t.length);
  return cutoffs.map((c) => {
    let n = 0;
    while (n < t.length && t[n] <= c) n++;
    return n > 1 ? trapz(n) / total : 0;
  });
}

function collectMoms(gaDays: number, mf: MaternalFactors, b: Biomarkers, warnings: string[]): Record<string, number> {
  const moms: Record<string, number> = {};
  if (b.map_mom != null) moms.map = b.map_mom;
  else if (b.map_mmhg != null) moms.map = b.map_mmhg / 10 ** expectedLog10Map(gaDays, mf);

  if (b.utpi_mom != null) moms.utpi = b.utpi_mom;
  else if (b.utpi_left != null && b.utpi_right != null) moms.utpi = (b.utpi_left + b.utpi_right) / 2 / 10 ** expectedLog10Utpi(gaDays, mf);
  else if ((b.utpi_left == null) !== (b.utpi_right == null)) warnings.push("UtA-PI needs both left and right values; UtA-PI not used.");

  if (b.plgf_mom != null) moms.plgf = b.plgf_mom;
  else if (b.plgf_pg_ml != null) {
    if (b.plgf_analyser == null) warnings.push("PlGF analyser not given; PlGF not used.");
    else moms.plgf = b.plgf_pg_ml / 10 ** expectedLog10Plgf(b.plgf_ga_days ?? gaDays, mf, b.plgf_analyser);
  }

  const trunc = COEF.data.truncation ?? {};
  for (const k of Object.keys(moms)) {
    const [lo, hi] = trunc[k] ?? [0, Infinity];
    const v = moms[k];
    if (v < lo || v > hi) {
      warnings.push(`${k.toUpperCase()} MoM ${v.toFixed(2)} outside ${pyFloat(lo)}-${pyFloat(hi)}; truncated.`);
      moms[k] = Math.min(Math.max(v, lo), hi);
    }
  }
  return moms;
}

const hasLikelihood = () => {
  const lk = COEF.data.likelihood ?? {};
  return !!lk.markers && Object.keys(lk.markers).length > 0 && lk.covariance != null;
};

const estimate = (c: number, p: number): RiskEstimate => ({ cutoff_weeks: c, probability: p, one_in: oneIn(p) });

export function assess(gaDays: number, mf: MaternalFactors, b: Biomarkers, cutoffs = DEFAULT_CUTOFFS): RiskReport {
  const warnings: string[] = [];
  if (!(gaDays >= WINDOW_DAYS[0] && gaDays < WINDOW_DAYS[1] + 1)) { // 13+6 = any time on day 97
    throw new Error(`gestational age ${pyFloat(gaDays)} days is outside 11+0 to 13+6 weeks (${WINDOW_DAYS[0]}-${WINDOW_DAYS[1]} days)`);
  }
  for (const comp of ["prior", "mom", "likelihood", "truncation"]) {
    if (comp === "likelihood" && !hasLikelihood()) continue;
    const level = COEF.data[comp].verification;
    if (level !== "verified") warnings.push(`Coefficients for '${comp}' are '${level}', not verified: not for clinical use.`);
  }
  const gaW = gaDays / 7;
  const mu = priorTerms(mf, warnings).reduce((s, [, v]) => s + v, 0);
  const sd = COEF.data.prior.sd;
  const mfOnly = cutoffs.map((c) => estimate(c, priorRisk(mu, sd, gaW, c)));

  const moms = collectMoms(gaDays, mf, b, warnings);
  let combined: RiskEstimate[] | null = null;
  if (Object.keys(moms).length) {
    if (hasLikelihood()) {
      const log10: Record<string, number> = {};
      for (const [k, v] of Object.entries(moms)) log10[k] = Math.log10(v);
      combined = posteriorRisks(mu, sd, gaW, log10, cutoffs).map((p, i) => estimate(cutoffs[i], p));
    } else {
      warnings.push("Biomarker likelihood parameters are missing; showing risk from maternal factors only. MoMs are reported but not combined.");
    }
  }
  return {
    model_label: COEF.label,
    model_checksum: COEF.checksum,
    prior_mean_weeks: mu,
    prior_sd_weeks: sd,
    moms,
    maternal_factors_only: mfOnly,
    combined,
    markers_used: combined ? Object.keys(moms).sort() : [],
    warnings,
  };
}
